"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[51518],{3331:(e,s,t)=>{t.d(s,{R:()=>o,x:()=>a});var n=t(36672);const i={},r=n.createContext(i);function o(e){const s=n.useContext(r);return n.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function a(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),n.createElement(r.Provider,{value:s},e.children)}},67047:(e,s,t)=>{t.r(s),t.d(s,{assets:()=>l,contentTitle:()=>a,default:()=>c,frontMatter:()=>o,metadata:()=>n,toc:()=>u});const n=JSON.parse('{"id":"2023/04/16","title":"2023-04-16","description":"Valve restreint les comptes de 2500 utilisateurs qui ont marqu\xe9 une critique de jeu n\xe9gative comme \xe9tant utile.","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/2023/04/16.md","sourceDirName":"2023/04","slug":"/2023/04/16","permalink":"/fr/2023/04/16","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/fr/docusaurus-plugin-content-docs//current/2023/04/16.md","tags":[],"version":"current","frontMatter":{"localized_date":"16 avril 2023","top_news":"Valve restreint les comptes de 2500 utilisateurs qui ont marqu\xe9 une critique de jeu n\xe9gative comme \xe9tant utile."},"sidebar":"defaultSidebar","previous":{"title":"2023-04-17","permalink":"/fr/2023/04/17"},"next":{"title":"2023-04-15","permalink":"/fr/2023/04/15"}}');var i=t(23420),r=t(3331);const o={localized_date:"16 avril 2023",top_news:"Valve restreint les comptes de 2500 utilisateurs qui ont marqu\xe9 une critique de jeu n\xe9gative comme \xe9tant utile."},a="2023-04-16",l={},u=[{value:"Valve restreint les comptes de 2500 utilisateurs qui ont marqu\xe9 une critique de jeu n\xe9gative comme \xe9tant utile.",id:"valve-restreint-les-comptes-de-2500-utilisateurs-qui-ont-marqu\xe9-une-critique-de-jeu-n\xe9gative-comme-\xe9tant-utile",level:2},{value:"Pourquoi un sandwich \xe0 la dinde emball\xe9 dans du plastique co\xfbte-t-il 15 dollars \xe0 l&#39;a\xe9roport de New York ?",id:"pourquoi-un-sandwich-\xe0-la-dinde-emball\xe9-dans-du-plastique-co\xfbte-t-il-15-dollars-\xe0-la\xe9roport-de-new-york-",level:2},{value:"Lofi contr\xf4le du trafic a\xe9rien - LAX",id:"lofi-contr\xf4le-du-trafic-a\xe9rien---lax",level:2},{value:"Que sont les mod\xe8les de transformateurs et comment fonctionnent-ils ?",id:"que-sont-les-mod\xe8les-de-transformateurs-et-comment-fonctionnent-ils-",level:2},{value:"WebGPU Fundamentals",id:"webgpu-fundamentals",level:2},{value:"PDG de Google : &quot;pouvons-nous changer les param\xe8tres de ce groupe pour qu&#39;il n&#39;y ait plus d&#39;historique&quot; [pdf](en anglais)",id:"pdg-de-google--pouvons-nous-changer-les-param\xe8tres-de-ce-groupe-pour-quil-ny-ait-plus-dhistorique-pdfen-anglais",level:2},{value:"Survivre \xe0 l&#39;\xe9puisement professionnel (2015)",id:"survivre-\xe0-l\xe9puisement-professionnel-2015",level:2},{value:"Le d\xe9veloppement de logiciels \xe0 faible code est un mensonge",id:"le-d\xe9veloppement-de-logiciels-\xe0-faible-code-est-un-mensonge",level:2},{value:"Vuln\xe9rabilit\xe9 d&#39;ex\xe9cution de code \xe0 distance dans Google qu&#39;ils ne sont pas pr\xeats \xe0 corriger",id:"vuln\xe9rabilit\xe9-dex\xe9cution-de-code-\xe0-distance-dans-google-quils-ne-sont-pas-pr\xeats-\xe0-corriger",level:2},{value:"D\xe9veloppement d&#39;un hyperviseur en Rust",id:"d\xe9veloppement-dun-hyperviseur-en-rust",level:2}];function d(e){const s={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(s.header,{children:(0,i.jsx)(s.h1,{id:"2023-04-16",children:"2023-04-16"})}),"\n",(0,i.jsx)(s.h2,{id:"valve-restreint-les-comptes-de-2500-utilisateurs-qui-ont-marqu\xe9-une-critique-de-jeu-n\xe9gative-comme-\xe9tant-utile",children:"Valve restreint les comptes de 2500 utilisateurs qui ont marqu\xe9 une critique de jeu n\xe9gative comme \xe9tant utile."}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://tech.slashdot.org/story/23/04/14/175246/valve-restricts-accounts-of-2500-users-who-marked-a-negative-game-review-useful",children:"Original"}),".\nValve a restreint les comptes de 2 500 utilisateurs qui ont jug\xe9 utile une critique n\xe9gative de Warlander, ce qui entra\xeene une interdiction de 30 jours de voter \xe0 la hausse ou \xe0 la baisse pour les personnes concern\xe9es. Les mod\xe9rateurs de Steam ont class\xe9 l'avis dans la cat\xe9gorie \"tentative d'escroquerie ou autres violations des r\xe8gles et directives de Steam\", ce qui a entra\xeen\xe9 la suppression de l'avis, et de nombreuses personnes ont estim\xe9 que le syst\xe8me d'avis \xe9tait \"compl\xe8tement inutile\" en raison de l'impact des actions de Valve."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35577895",children:"Discussion Service"}),".\nValve restreint les comptes des utilisateurs qui ont jug\xe9 utile un avis n\xe9gatif sur un jeu, ce qui a conduit les utilisateurs de Hacker News \xe0 critiquer le fait que Valve autorise les \"logiciels malveillants\" sur sa plateforme. Certains sugg\xe8rent des alternatives aux logiciels anti-triche, tandis que d'autres affirment qu'ils sont n\xe9cessaires pour emp\xeacher la tricherie dans les jeux en ligne. Les commentaires discutent de l'\xe9thique du monopole de Steam sur la distribution des jeux vid\xe9o sur PC, avec des opinions divergentes sur la n\xe9cessit\xe9 des monopoles et l'efficacit\xe9 des logiciels anti-triche."]}),"\n",(0,i.jsx)(s.h2,{id:"pourquoi-un-sandwich-\xe0-la-dinde-emball\xe9-dans-du-plastique-co\xfbte-t-il-15-dollars-\xe0-la\xe9roport-de-new-york-",children:"Pourquoi un sandwich \xe0 la dinde emball\xe9 dans du plastique co\xfbte-t-il 15 dollars \xe0 l'a\xe9roport de New York ?"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://hellgatenyc.com/why-is-airport-turkey-sandwich-expensive",children:"https://hellgatenyc.com/why-is-airport-turkey-sandwich-expensive"}),").\nN/A."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35580847",children:"Discussion Service"}),".\nLes utilisateurs de Discussion Service d\xe9battent des raisons pour lesquelles un sandwich \xe0 la dinde emball\xe9 dans du plastique co\xfbte 15 dollars dans les a\xe9roports de New York ; la concurrence limit\xe9e dans les a\xe9roports et le manque de comparables pour les vendeurs de F&B rendent impossible la garantie d'une tarification \xe9quitable. Les utilisateurs sugg\xe8rent aux passagers d'apporter leurs propres repas."]}),"\n",(0,i.jsx)(s.h2,{id:"lofi-contr\xf4le-du-trafic-a\xe9rien---lax",children:"Lofi contr\xf4le du trafic a\xe9rien - LAX"}),"\n",(0,i.jsxs)(s.p,{children:["(Original) (",(0,i.jsx)(s.a,{href:"https://www.lofiatc.com/?icao=KLAX",children:"https://www.lofiatc.com/?icao=KLAX"}),").\nLe message partage la fr\xe9quence de la tour de Los Angeles (Nord) \xe0 KLAX, qui est de 133.900. Le message inclut une vid\xe9o musicale de Glimlip x Yasper et propose une option pour les commentaires ou les dons."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35583228",children:"Discussion Service"}),".\nLes utilisateurs de Hacker News discutent de lofiatc.com, une nouvelle application web qui combine la musique ambiante avec les communications du contr\xf4le du trafic a\xe9rien d'une mani\xe8re apaisante, suscitant l'int\xe9r\xeat ; certains utilisateurs demandent des fonctionnalit\xe9s suppl\xe9mentaires et des conversations radio. Les utilisateurs font \xe9galement part de leurs pr\xe9f\xe9rences en mati\xe8re de musique d'ambiance pendant le travail, recommandant SomaFM et mynoise.net, et quelques-uns sugg\xe9rant le black metal comme alternative appropri\xe9e, bien qu'il n'y ait pas de consensus clair sur le meilleur type de musique d'ambiance pour la concentration."]}),"\n",(0,i.jsx)(s.h2,{id:"que-sont-les-mod\xe8les-de-transformateurs-et-comment-fonctionnent-ils-",children:"Que sont les mod\xe8les de transformateurs et comment fonctionnent-ils ?"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://txt.cohere.ai/what-are-transformer-models/",children:"Original"}),".\nLes mod\xe8les transformateurs sont un nouveau d\xe9veloppement dans le domaine de l'apprentissage automatique et sont capables de g\xe9n\xe9rer un texte coh\xe9rent en suivant le contexte. Capables d'effectuer diverses t\xe2ches, telles que la traduction entre langues et la r\xe9ponse \xe0 des questions, les transformateurs se composent de divers \xe9l\xe9ments, notamment la tokenisation, l'int\xe9gration, l'encodage positionnel, les blocs de transformation et le softmax. Le bloc de transformation le plus complexe utilise des composants d'attention et de r\xe9troaction, l'attention multi-t\xeates \xe9tant utilis\xe9e pour modifier les vecteurs et fournir plus de contexte. Le post-entra\xeenement apprend aux transformateurs \xe0 effectuer des t\xe2ches sp\xe9cifiques, et leur capacit\xe9 \xe0 saisir le contexte est \xe0 l'origine de leur succ\xe8s."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35576918",children:"Discussion Service"}),".\nLes utilisateurs engagent des discussions sur les mod\xe8les de transformateurs, remettant en question leur efficacit\xe9 et l'exhaustivit\xe9 du contenu promotionnel. Des m\xe9thodes alternatives de tokenisation sont mentionn\xe9es et des ressources pour en savoir plus sont recommand\xe9es, y compris des cours, des vid\xe9os et des articles. Le comportement \xe9mergent montr\xe9 par des mod\xe8les simples en intelligence artificielle et le lien entre les d\xe9tails informatiques et le comportement de haut niveau sont explor\xe9s, mettant en \xe9vidence un domaine d'\xe9tude actif appel\xe9 interpr\xe9tabilit\xe9 m\xe9caniste."]}),"\n",(0,i.jsx)(s.h2,{id:"webgpu-fundamentals",children:"WebGPU Fundamentals"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://webgpufundamentals.org/",children:"Original"}),".\nCe billet fournit un ensemble d'articles pour apprendre les principes fondamentaux du WebGPU, y compris la disposition de la m\xe9moire de donn\xe9es, les math\xe9matiques 3D et le WebGPU \xe0 partir de WebGL. L'article comprend \xe9galement des ressources et des r\xe9f\xe9rences pour approfondir l'\xe9tude, ainsi que des possibilit\xe9s de contribution. Merci \xe0 jrprice pour ses contributions."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35579334",children:"Discussion Service"}),".\nWebGPU Fundamentals attire l'attention sur Hacker News en tant que successeur de WebGL pour les graphiques sur les navigateurs web. Les utilisateurs discutent des applications potentielles pour la simulation, l'apprentissage en profondeur, et des pr\xe9occupations concernant la multiplication des fonctionnalit\xe9s des navigateurs. Les commentaires portent \xe9galement sur les s\xe9quenceurs MIDI bas\xe9s sur le web, les instruments exp\xe9rimentaux et le WebUSB pour les mises \xe0 jour du micrologiciel. Certains font valoir les avantages des outils bas\xe9s sur le web, tandis que d'autres s'inqui\xe8tent des risques de s\xe9curit\xe9 et des probl\xe8mes de compatibilit\xe9. WebGPU n'est pas cens\xe9 \xeatre un outil de haut niveau ou accessible aux d\xe9butants, mais une API GPU de bas niveau pour les utilisateurs experts."]}),"\n",(0,i.jsx)(s.h2,{id:"pdg-de-google--pouvons-nous-changer-les-param\xe8tres-de-ce-groupe-pour-quil-ny-ait-plus-dhistorique-pdfen-anglais",children:"PDG de Google : \"pouvons-nous changer les param\xe8tres de ce groupe pour qu'il n'y ait plus d'historique\" [pdf](en anglais)"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://ia601707.us.archive.org/28/items/gov.uscourts.cand.364454/gov.uscourts.cand.364454.385.0.pdf",children:"Original"}),".\nHacker News discute de WebGPU Fundamentals, le successeur de WebGL, pour son potentiel en mati\xe8re d'apprentissage profond c\xf4t\xe9 client et de simulations dans les navigateurs. Les conversations portent \xe9galement sur la multiplication des fonctionnalit\xe9s des navigateurs, leur utilit\xe9 potentielle et leur commodit\xe9, ainsi que sur la port\xe9e des navigateurs en tant qu'applications ou visionneuses. En outre, les utilisateurs discutent des moyens de rendre du texte \xe0 l'aide de WebGPU, de sa compatibilit\xe9 avec les projets d'IA et de la collaboration en cours entre les \xe9quipes de WebGPU."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35585174",children:"Discussion Service"}),".\nLe PDG de Google, Sundar Pichai, est accus\xe9 d'avoir demand\xe9 que les param\xe8tres du groupe Google Chat soient modifi\xe9s de mani\xe8re \xe0 ce que l'historique soit d\xe9sactiv\xe9, malgr\xe9 les implications juridiques potentielles et la violation de l'article 37(e) du FRCP. Les utilisateurs de Discussion Service discutent de l'importance de pr\xe9server les enregistrements communicables et des pr\xe9occupations concernant la l\xe9galit\xe9 des pratiques de suppression automatique, avec des exemples d'autres communications \xe9lectroniques qui suppriment les messages. En outre, des discussions sur la conservation des donn\xe9es, les r\xe9glementations gouvernementales et les monopoles \xe0 l'\xe9chelle mondiale sont partag\xe9es, tandis que des pr\xe9occupations concernant l'activit\xe9 Android de Google et son manque de concurrence sont soulev\xe9es."]}),"\n",(0,i.jsx)(s.h2,{id:"survivre-\xe0-l\xe9puisement-professionnel-2015",children:"Survivre \xe0 l'\xe9puisement professionnel (2015)"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://lifeofaudrey.com/essays/surviving_burnout.html",children:"Original"}),".\nL'\xe9puisement professionnel dans l'industrie technologique est caus\xe9 par un mauvais alignement des responsabilit\xe9s, de l'autorit\xe9 et des ressources. L'exp\xe9rience de l'auteur en mati\xe8re d'\xe9puisement professionnel l'a pouss\xe9e \xe0 quitter son emploi et \xe0 entamer une p\xe9riode de r\xe9tablissement qui l'a amen\xe9e \xe0 cr\xe9er sa propre entreprise. L'\xe9puisement professionnel est un probl\xe8me structurel qui n\xe9cessite des solutions structurelles, avec un soutien au r\xe9tablissement et des fonds n\xe9cessaires pour les personnes touch\xe9es."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35577285",children:"Discussion Service"}),".\nUn article sur Hacker News traite de l'importance de trouver un \xe9quilibre pour \xe9viter l'\xe9puisement professionnel et pr\xe9server la sant\xe9 mentale et physique, tandis que les utilisateurs partagent leurs exp\xe9riences personnelles et donnent des conseils. Certains utilisateurs de Discussion Service soulignent les diff\xe9rences entre la d\xe9pression et l'\xe9puisement professionnel, tandis que d'autres proposent des conseils pour faire face \xe0 un environnement de travail propice \xe0 l'\xe9puisement professionnel ou \xe0 la cr\xe9ation d'une entreprise comme solution potentielle. Plusieurs lecteurs discutent \xe9galement de l'efficacit\xe9 d'un coach de vie ou d'un th\xe9rapeute pour lutter contre l'\xe9puisement professionnel des employ\xe9s, avec des opinions mitig\xe9es. En fin de compte, le principal enseignement \xe0 tirer est qu'il est important de se pr\xe9occuper de son travail, mais pas au d\xe9triment de son bien-\xeatre."]}),"\n",(0,i.jsx)(s.h2,{id:"le-d\xe9veloppement-de-logiciels-\xe0-faible-code-est-un-mensonge",children:"Le d\xe9veloppement de logiciels \xe0 faible code est un mensonge"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://jaylittle.com/post/view/2023/4/low-code-software-development-is-a-lie",children:"https://jaylittle.com/post/view/2023/4/low-code-software-development-is-a-lie"}),").\nUn d\xe9veloppeur de logiciels exp\xe9riment\xe9 affirme que la cr\xe9ation de logiciels est difficile parce que les clients et les d\xe9veloppeurs ne comprennent pas les causes profondes des probl\xe8mes qu'ils veulent r\xe9soudre, plut\xf4t que par la faute des langages et des outils de codage. L'auteur critique l'id\xe9e d'outils \"low code\" tels qu'OutSystems, affirmant qu'ils n'\xe9liminent pas la complexit\xe9 inh\xe9rente et peuvent conduire \xe0 des syst\xe8mes logiciels mal pens\xe9s, tout en \xe9tant co\xfbteux et en impliquant un verrouillage du fournisseur. Concevoir correctement une solution est la partie la plus difficile du processus de d\xe9veloppement logiciel, et aucun outil ne peut remplacer la r\xe9flexion, la discussion et la planification n\xe9cessaires."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35578240",children:"Discussion Service"}),".\nLe d\xe9veloppement de logiciels \xe0 code bas est utile pour les probl\xe8mes simples mais inadapt\xe9 pour les probl\xe8mes complexes, et ne devrait pas remplacer compl\xe8tement les d\xe9veloppeurs. Les commentaires de Discussion Service discutent des limites et des compromis des plates-formes \xe0 code bas, y compris la faible testabilit\xe9, les versions et les outils de d\xe9bogage qui peuvent conduire \xe0 un verrouillage du fournisseur. Certains experts sugg\xe8rent que les outils \"low-code\" peuvent \xeatre utiles pour le prototypage et certaines applications, mais d'autres mettent en garde contre une d\xe9pendance excessive \xe0 leur \xe9gard et conseillent de s\xe9lectionner soigneusement les outils appropri\xe9s. Bien que les cas d'utilisation du low-code soient vari\xe9s, la d\xe9finition est floue et potentiellement trompeuse, Excel et les graphes de shaders en \xe9tant des exemples."]}),"\n",(0,i.jsx)(s.h2,{id:"vuln\xe9rabilit\xe9-dex\xe9cution-de-code-\xe0-distance-dans-google-quils-ne-sont-pas-pr\xeats-\xe0-corriger",children:"Vuln\xe9rabilit\xe9 d'ex\xe9cution de code \xe0 distance dans Google qu'ils ne sont pas pr\xeats \xe0 corriger"}),"\n",(0,i.jsxs)(s.p,{children:["(",(0,i.jsx)(s.a,{href:"https://giraffesecurity.dev/posts/google-remote-code-execution/",children:"https://giraffesecurity.dev/posts/google-remote-code-execution/"}),").\nUn chercheur en s\xe9curit\xe9 a d\xe9couvert une vuln\xe9rabilit\xe9 dans Google qui lui a permis d'ex\xe9cuter un code arbitraire sur les ordinateurs de plus de 50 employ\xe9s de Google, caus\xe9e par une confusion des d\xe9pendances dans le syst\xe8me de gestion de Python. Google l'a d'abord class\xe9e comme grave, mais l'a ensuite transform\xe9e en comportement pr\xe9vu. Le chercheur craint que la vuln\xe9rabilit\xe9 puisse \xeatre exploit\xe9e, car il re\xe7oit quotidiennement des t\xe9l\xe9chargements de la part d'employ\xe9s de Google, et il soup\xe7onne Google de ne pas comprendre le probl\xe8me ou de ne pas se soucier de le corriger."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35581532",children:"Discussion Service"}),".\nUne vuln\xe9rabilit\xe9 d'ex\xe9cution de code \xe0 distance (RCE) d\xe9couverte dans le logiciel de Google ne serait pas corrig\xe9e, certains utilisateurs soulignant que le syst\xe8me de gestion de paquets de Java dispose d'un moyen plus s\xfbr de t\xe9l\xe9charger des paquets que le syst\xe8me de Rust, tandis que d'autres sugg\xe8rent que ",(0,i.jsx)(s.code,{children:"pip install --extra-index-url"})," ignore les registres sp\xe9cifiques \xe0 l'utilisateur, ce qui rend les registres priv\xe9s inutilisables. Google a mis en place des mesures de s\xe9curit\xe9 de type \"confiance z\xe9ro\" pour lutter contre les menaces internes, mais un APT pourrait utiliser cette vuln\xe9rabilit\xe9 pour s'implanter dans l'environnement. La n\xe9cessit\xe9 de meilleures solutions de gestion des paquets et le r\xf4le de la confiance z\xe9ro dans la pr\xe9vention de telles attaques sont \xe9galement soulign\xe9s."]}),"\n",(0,i.jsx)(s.h2,{id:"d\xe9veloppement-dun-hyperviseur-en-rust",children:"D\xe9veloppement d'un hyperviseur en Rust"}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"https://memn0ps.github.io/hypervisor-development-in-rust-part-1/",children:"Original"}),".\nCet article d\xe9crit le d\xe9veloppement d'un hyperviseur de recherche bas\xe9 sur Rust pour la virtualisation Intel VT-x, en fournissant des exemples de code Rust pour le fonctionnement de VMX et en discutant du processus d'initialisation des r\xe9gions de m\xe9moire pour les CPU virtuels. Il vise \xe0 \xeatre une ressource utile pour les experts dans le domaine de la virtualisation utilisant Rust. L'article maintient la neutralit\xe9 et fournit des r\xe9f\xe9rences et des cr\xe9dits."]}),"\n",(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35579876",children:"Discussion Service"}),".\nUn utilisateur de Hacker News commente l'article sur la virtualisation des processeurs et exprime son int\xe9r\xeat pour la virtualisation des p\xe9riph\xe9riques, en soulignant les d\xe9fis rencontr\xe9s et en proposant de nouvelles solutions. D'autres utilisateurs fournissent des ressources et des alternatives pour les utilisateurs de Linux int\xe9ress\xe9s par ce domaine."]})]})}function c(e={}){const{wrapper:s}={...(0,r.R)(),...e.components};return s?(0,i.jsx)(s,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}}}]);